/**
 * Sums quantity * price for each item, rounded to 2 decimal places.
 * Throws a RangeError if any item has a negative quantity or price.
 *
 * @param {Array<{quantity: number, price: number}>} items
 * @returns {number} Total rounded to 2 decimal places; 0 for an empty array.
 */
export function total(items) {
  let sum = 0;
  for (const item of items) {
    if (item.quantity < 0) {
      throw new RangeError(`Invalid item: quantity must not be negative (got ${item.quantity}).`);
    }
    if (item.price < 0) {
      throw new RangeError(`Invalid item: price must not be negative (got ${item.price}).`);
    }
    sum += item.quantity * item.price;
  }
  return Math.round(sum * 100) / 100;
}

